def choose_model(prompt, tools_needed):
    # cheap heuristics first -- no model call needed
    if tools_needed or len(prompt) > 4000:
        return "frontier"
    if any(kw in prompt.lower() for kw in ("prove", "debug", "design")):
        return "frontier"
    return "small"        # default the easy majority to cheap/fast

tier = choose_model(user_prompt, tools_needed=False)

def call_with_fallback(prompt, chain):
    last_error = None
    for model_name in chain:            # e.g. ["primary", "secondary", "cheap"]
        try:
            return call_model(model_name, prompt)
        except (TimeoutError, ProviderError) as e:
            last_error = e              # log and try the next model
            continue
    raise RuntimeError(f"all models failed: {last_error}")

RETRYABLE = (TimeoutError, RateLimitError, ServerError)  # 429 / 5xx

def attempt(model_name, prompt, timeout_s=8):
    try:
        return call_model(model_name, prompt, timeout=timeout_s)
    except RETRYABLE:
        raise                     # signal: fall back to next model
    except BadRequestError:
        raise Terminal            # signal: don't retry, it'll fail everywhere

from collections import Counter

metrics = Counter()

def routed_call(prompt):
