CHAINS = {
    "easy": ["small", "frontier"],       # small first, escalate on failure
    "hard": ["frontier", "small"],       # frontier first, degrade if it fails
}

def call_model(name, prompt):
    if name == "frontier":
        raise TimeoutError_("frontier timed out")   # simulate an outage
    return f"[{name}] answered: {prompt[:20]}"

def call_with_fallback(prompt, chain):
    last = None
    for name in chain:
        try:
            return call_model(name, prompt)
        except TimeoutError_ as e:
            last = e            # retryable -> try next model
    raise RuntimeError(f"all failed: {last}")

prompt = "classify this ticket"
tier = choose_tier(prompt)
print("tier:", tier)
print(call_with_fallback(prompt, CHAINS[tier]))

class RateLimit(Exception):
    pass

class BadRequest(Exception):
    pass

RETRYABLE = (RateLimit,)

def call_model(name, prompt):
    if prompt == "bad":
        raise BadRequest("invalid input")     # terminal: fails everywhere
    if name == "primary":
        raise RateLimit("429")                 # transient: try next
    return f"[{name}] ok"

def call_with_fallback(prompt, chain):
    last = None
    for name in chain:
        try:
            return call_model(name, prompt)
        except RETRYABLE as e:
            last = e                            # fall back to next model
        except BadRequest:
            raise                               # short-circuit, don't retry
    raise RuntimeError(f"all failed: {last}")

chain = ["primary", "secondary"]
print(call_with_fallback("hello", chain))       # primary 429 -> secondary
try:
    call_with_fallback("bad", chain)            # BadRequest, no fallback
except BadRequest as e:
    print("terminal, not retried:", e)

